const PIECES = ["", "a", ",", "::", "b", ":", ",,", "ab", "@"];
const pieces = (next: ReturnType<typeof seeded>, parts: number): string =>
  Array.from({ length: next(0, parts) }, () => PIECES[next(1, PIECES.length - 1)]).join("");

